import React from 'react'
import type { ChipsProps } from './Chip'
import Chip from './Chip'

export default {
  title: 'Components/Chip',
  component: Chip,
  argTypes: {
    onClick: {
      control: { type: 'select' },
      options: ['None', 'Click handler'],
    },
    onDelete: {
      control: { type: 'select' },
      options: ['None', 'Click handler'],
    },
  },
  args: {
    label: 'Text',
    onClick: 'Click handler',
    onDelete: 'Click handler',
  },
}

const handleClick = () => {
  alert('clicked')
}

const handleDelete = () => {
  alert('deleted')
}

function Template(
  args: ChipsProps & { onClick: string; onDelete: string },
): JSX.Element {
  return (
    <Chip
      {...args}
      onClick={args.onClick === 'Click handler' ? handleClick : undefined}
      onDelete={args.onDelete === 'Click handler' ? handleDelete : undefined}
    />
  )
}

export const Default = {
  render: Template,
}
